using System;using System.IO;using System.Diagnostics;using System.Text.RegularExpressions;using System.Windows.Forms;
class DistributionLauncher {
 [STAThread] static void Main(){try{string root=AppDomain.CurrentDomain.BaseDirectory;string version=File.ReadAllText(Path.Combine(root,"current.txt")).Trim();if(!Regex.IsMatch(version,@"^\d+\.\d+\.\d+$"))throw new Exception("Неверный номер версии JARVIS.");string directory=Path.Combine(root,"versions",version),exe=Path.Combine(directory,"JARVIS-runtime.exe");if(!File.Exists(exe))throw new Exception("Не найдены файлы JARVIS. Распакуйте архив целиком или повторите установку.");var start=new ProcessStartInfo(exe){WorkingDirectory=directory,UseShellExecute=false};start.EnvironmentVariables["JARVIS_DISTRIBUTION_ROOT"]=root.TrimEnd(Path.DirectorySeparatorChar);start.EnvironmentVariables.Remove("ELECTRON_RUN_AS_NODE");Process.Start(start);}catch(Exception e){MessageBox.Show(e.Message,"JARVIS",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
}
